<?php
namespace App\Http\Controllers;
use App\Models\{Event,Category,Organization}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class AdminEventController extends Controller { public function index(){return view('admin.events.index',['events'=>Event::with('category')->latest()->paginate(15)]);} public function create(){return view('admin.events.form',['event'=>new Event,'categories'=>Category::where('type','event')->get()]);} public function store(Request $r){$d=$r->validate(['title'=>'required|max:190','summary'=>'nullable|max:1000','description'=>'nullable','type'=>'required|in:cinema,theater','category_id'=>'nullable|exists:categories,id','duration'=>'nullable|integer|min:1','age_rating'=>'nullable|max:20','release_date'=>'nullable|date','is_featured'=>'nullable|boolean','status'=>'required|in:draft,published,archived','poster'=>'nullable|image|max:5120','gallery'=>'nullable|array','gallery.*'=>'image|max:5120','trailer'=>'nullable|mimetypes:video/mp4,video/webm,video/quicktime|max:51200']);$d['slug']=Str::slug($d['title']).'-'.Str::lower(Str::random(5));$d['organization_id']=Organization::firstOrCreate(['slug'=>'cinemaplus'],['name'=>'سینماپلاس'])->id;$d['is_featured']=$r->boolean('is_featured');$event=Event::create(collect($d)->except(['poster','gallery','trailer'])->all());if($r->hasFile('poster'))$event->addMediaFromRequest('poster')->toMediaCollection('poster');foreach($r->file('gallery',[]) as $file)$event->addMedia($file)->toMediaCollection('gallery');if($r->hasFile('trailer'))$event->addMediaFromRequest('trailer')->toMediaCollection('trailer');return redirect()->route('admin.events.index')->with('success','رویداد با رسانه‌ها ثبت شد.');} }
